import React, { useState, useCallback, useEffect } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';
import { HomeScreen } from './screens/HomeScreen';
import { LessonScreen } from './screens/LessonScreen';
import { FavoritesScreen } from './screens/FavoritesScreen';
import {
  loadProgress,
  saveProgress,
  updateLessonProgress,
  toggleFavorite,
  checkBadges,
} from './storage';
import {
  getSpeechDebugState,
  preloadVoices,
  subscribeSpeechDebug,
  testSpeech,
  type SpeechDebugState,
} from './speech';
import type { Screen } from './types';

// ─── Atlantis header ──────────────────────────────────────────────────────────

const AtlantisBar = styled.header`
  display: flex;
  align-items: center;
  height: 48px;
  background: ${theme.colors.sidebarBg};
  border-bottom: 1px solid ${theme.colors.sidebarBorder};
  padding: 0 ${theme.spacing.lg};
  flex-shrink: 0;
  gap: ${theme.spacing.sm};
  z-index: 100;
`;

const AtlantisLogo = styled.a`
  display: flex;
  align-items: baseline;
  text-decoration: none;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  letter-spacing: -0.02em;
  color: ${theme.colors.mainText};
  flex-shrink: 0;
  transition: opacity 0.15s;
  &:hover { opacity: 0.8; }
  span { color: ${theme.colors.accent}; }
`;

const AppLabel = styled.div`
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 500;
  color: ${theme.colors.sidebarTextMuted};
  font-family: ${theme.typography.fontFamily};
  padding-left: ${theme.spacing.sm};
  &::before {
    content: '/';
    margin-right: ${theme.spacing.sm};
    color: ${theme.colors.border};
  }
`;

const AppShell = styled.div`
  display: flex;
  flex-direction: column;
  height: 100dvh;
  overflow: hidden;
`;

const ScreenArea = styled.div`
  flex: 1;
  min-height: 0;
  overflow-y: auto;
`;

// ─────────────────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App(_props: AppProps) {
  const [progress, setProgress] = useState(() => loadProgress());
  const [speechDebug, setSpeechDebug] = useState<SpeechDebugState>(() => getSpeechDebugState());

  useEffect(() => {
    preloadVoices();
    return subscribeSpeechDebug(setSpeechDebug);
  }, []);
  const [screen, setScreen] = useState<Screen>({ id: 'home' });

  const updateAndSave = useCallback((updater: (p: typeof progress) => typeof progress) => {
    setProgress((prev) => {
      const next = checkBadges(updater(prev));
      saveProgress(next);
      return next;
    });
  }, []);

  const handleToggleFavorite = useCallback((cardKey: string) => {
    updateAndSave((p) => toggleFavorite(p, cardKey));
  }, [updateAndSave]);

  const handleComplete = useCallback((lessonId: string, score: number, total: number) => {
    updateAndSave((p) => updateLessonProgress(p, lessonId, score, total));
    setScreen({ id: 'home' });
  }, [updateAndSave]);

  const header = (
    <AtlantisBar>
      <AtlantisLogo href="/" title="Atlantis Home">
        Atl<span>antis</span>
      </AtlantisLogo>
      <AppLabel>LêBem</AppLabel>
    </AtlantisBar>
  );

  if (screen.id === 'lesson') {
    return (
      <AppShell>
        {header}
        <ScreenArea>
          <LessonScreen
            lessonId={screen.lessonId}
            progress={progress}
            onBack={() => setScreen({ id: 'home' })}
            onComplete={handleComplete}
            onToggleFavorite={handleToggleFavorite}
          />
        </ScreenArea>
      </AppShell>
    );
  }

  if (screen.id === 'favorites') {
    return (
      <AppShell>
        {header}
        <ScreenArea>
          <FavoritesScreen
            progress={progress}
            onBack={() => setScreen({ id: 'home' })}
            onToggleFavorite={handleToggleFavorite}
          />
        </ScreenArea>
      </AppShell>
    );
  }

  return (
    <AppShell>
      {header}
      <ScreenArea>
        <HomeScreen
          progress={progress}
          speechDebug={speechDebug}
          onSelectLesson={(lessonId) => setScreen({ id: 'lesson', lessonId })}
          onOpenFavorites={() => setScreen({ id: 'favorites' })}
          onSpeechTest={testSpeech}
        />
      </ScreenArea>
    </AppShell>
  );
}
